def anti_shuffle(s):
    import re
    if not s or not s.strip():
        return s
    parts = re.split(r'(\s+)', s)
    result = []
    for part in parts:
        if part.isspace():
            result.append(part)
        else:
            result.append(''.join(sorted(part)))
    return ''.join(result)
